// 1. Constantes de fechas
const VACACIONES_ESCOLARES_GALICIA = [
  { inicio: "2026-06-23", fin: "2026-09-09" },   // Verano
  { inicio: "2025-12-22", fin: "2026-01-07" },   // Navidad
  { inicio: "2026-02-27", fin: "2026-03-03" },   // Entroido/Carnaval
  { inicio: "2026-03-30", fin: "2026-04-06" }    // Semana Santa
];

const FESTIVOS_2026 = [
  "2026-01-01", "2026-01-06", "2026-03-19", "2026-04-02", "2026-04-03",
  "2026-05-01", "2026-06-24", "2026-07-25", "2026-08-15", "2026-10-12",
  "2026-12-08", "2026-12-25"
];

// 2. Funciones auxiliares
function toISODate(date) { return date.toISOString().slice(0, 10); }
function addDays(date, n) {
  const d = new Date(date);
  d.setUTCDate(d.getUTCDate() + n);
  return d;
}
function esVacacionesEscolares(fechaISO) {
  return VACACIONES_ESCOLARES_GALICIA.some(p => fechaISO >= p.inicio && fechaISO <= p.fin);
}

// 3. Captura del periodo dinámico
const datosEntrada = $('Start').first().json || {};
const diasPeriodo = parseInt(datosEntrada.periodo) || 14; 

// 4. Lógica principal
const hoy = new Date(Date.UTC(new Date().getUTCFullYear(), new Date().getUTCMonth(), new Date().getUTCDate()));

const calendarioSerie = Array.from({ length: diasPeriodo }, (_, idx) => {
  const dias_vista = idx + 1;
  const fecha = toISODate(addDays(hoy, dias_vista));

  return {
    fecha,
    dias_vista,
    es_vacaciones_escolares: esVacacionesEscolares(fecha),
    es_festivo: FESTIVOS_2026.includes(fecha)
  };
});

return [{ json: { calendarioSerie } }];

const climaPorFecha = $('Preparar Clima').first().json.climaPorFecha || {};
const competenciaResumen = $('Preparar Competencia').first().json.competenciaResumen || null;
const calendarioSerie = $('Obtener Vacaciones Escolares').first().json.calendarioSerie || [];

const activarAjusteClima = true; // Forzado a true ya que el nodo de config no está presente en el flujo

const REGLAS_CLIMA = [
  { cumple: (c) => c.precipitacion < 1 && c.temp_max > 20, ajuste_pct: 0.05, motivo: 'buen tiempo previsto' },
  { cumple: (c) => c.precipitacion > 5, ajuste_pct: -0.05, motivo: 'mal tiempo previsto' }
];

function calcularAjuste(fechaISO, es_vacaciones, es_festivo) {
  let ajuste = 0;
  const motivos = [];

  if (es_vacaciones) {
    ajuste += 0.10;
    motivos.push('vacaciones escolares Galicia');
  }

  if (es_festivo) {
    ajuste += 0.08;
    motivos.push('festivo');
  }

  const clima = climaPorFecha[fechaISO];
  if (activarAjusteClima && clima) {
    const regla = REGLAS_CLIMA.find(r => r.cumple(clima));
    if (regla) {
      ajuste += regla.ajuste_pct;
      motivos.push(regla.motivo);
    }
  }

  ajuste = Math.max(-0.10, Math.min(0.15, ajuste));
  return { ajuste_pct: Number(ajuste.toFixed(3)), motivo_ajuste: motivos.join(', ') || 'sin ajuste' };
}

const contextoExternoSerie = calendarioSerie.map(dia => {
  const { ajuste_pct, motivo_ajuste } = calcularAjuste(dia.fecha, dia.es_vacaciones_escolares, dia.es_festivo);
  return {
    fecha: dia.fecha,
    dias_vista: dia.dias_vista,
    es_vacaciones_escolares: dia.es_vacaciones_escolares,
    es_festivo: dia.es_festivo,
    ajuste_pct,
    motivo_ajuste,
    clima: climaPorFecha[dia.fecha] || null
  };
});

return [{ json: { contextoExternoSerie, competenciaResumen } }];

const climaData = $json.daily;
let climaPorFecha = {};
let usando_clima_antiguo = false;
let advertenciaClima = null;

if (climaData && climaData.time) {
  climaData.time.forEach((fecha, i) => {
    climaPorFecha[fecha] = {
      temp_max: climaData.temperature_2m_max?.[i] ?? null,
      temp_min: climaData.temperature_2m_min?.[i] ?? null,
      precipitacion: climaData.precipitation_sum?.[i] ?? null
    };
  });
} else {
  usando_clima_antiguo = true;
  advertenciaClima = "La API de Open-Meteo falló o devolvió un formato inesperado. No se aplicó ajuste por clima en este periodo.";
}

return [{
  json: {
    climaPorFecha,
    usando_clima_antiguo,
    advertenciaClima,
    latitude: $json.latitude,
    longitude: $json.longitude
  }
}];

let hoteles = $json.data?.data;
let usando_datos_antiguos = false;
let advertencia = null;

if (!Array.isArray(hoteles) || hoteles.length === 0 || $json.error) {
  usando_datos_antiguos = true;
  advertencia = "La API de TripAdvisor falló (posible límite de peticiones o formato inesperado). Se utilizaron los datos de respaldo.";

  hoteles = [
    {
      id: "2525720",
      title: "1. Hostal Alce",
      secondaryInfo: "Nigran, Galicia, Spain",
      bubbleRating: { count: "(26)", rating: 2.4 },
      priceForDisplay: "€45",
      badge: {}
    },
    {
      id: "235123",
      title: "2. Parador de Baiona",
      secondaryInfo: "Baiona, Province of Pontevedra, Galicia",
      bubbleRating: { count: "(2,145)", rating: 4.5 },
      priceForDisplay: "€230",
      badge: {}
    },
    {
      id: "576135",
      title: "3. Hotel Bahia Bayona",
      secondaryInfo: "Baiona, Province of Pontevedra, Galicia",
      bubbleRating: { count: "(892)", rating: 4.0 },
      priceForDisplay: "€75",
      badge: {}
    },
    {
      id: "1456298",
      title: "4. Hotel Rompeolas",
      secondaryInfo: "Baiona, Province of Pontevedra, Galicia",
      bubbleRating: { count: "(341)", rating: 4.0 },
      priceForDisplay: "€65",
      badge: {}
    },
    {
      id: "678912",
      title: "5. Arce",
      secondaryInfo: "Baiona, Province of Pontevedra, Galicia",
      bubbleRating: { count: "(150)", rating: 4.5 },
      priceForDisplay: "€80",
      badge: {}
    }
  ];
}

const hotelesProcesados = hoteles
  .map(h => ({
    nombre: (h.title || '').replace(/^\d+\.\s*/, ''),
    rating: h.bubbleRating?.rating ?? null,
    numResenas: h.bubbleRating?.count
      ? Number(String(h.bubbleRating.count).replace(/[(),]/g, ''))
      : null,
    // Extrae solo dígitos del precio mostrado (ej. "€69" -> 69). null si no viene precio.
    precio: h.priceForDisplay
      ? Number(String(h.priceForDisplay).replace(/[^\d]/g, '')) || null
      : null,
    esTravellerChoice: h.badge?.type === 'TRAVELLER_CHOICE'
  }))
  .filter(h => h.rating !== null);

const ratingMedio = hotelesProcesados.length
  ? Number((hotelesProcesados.reduce((sum, h) => sum + h.rating, 0) / hotelesProcesados.length).toFixed(2))
  : null;

// Media de precios, excluyendo los que no tienen precio disponible
const hotelesConPrecio = hotelesProcesados.filter(h => h.precio !== null);
const precioMedio = hotelesConPrecio.length
  ? Number((hotelesConPrecio.reduce((sum, h) => sum + h.precio, 0) / hotelesConPrecio.length).toFixed(2))
  : null;

const competenciaResumen = {
  hoteles: hotelesProcesados,
  ratingMedioZona: ratingMedio,
  precioMedioZona: precioMedio,
  numCompetidores: hotelesProcesados.length,
  usando_datos_antiguos,
  advertencia
};

return [{ json: { competenciaResumen } }];;
